   "type": "calculation",
   "title": "Elevon end gaps",
   "script": "redesign/team/A5/cad_claims.py",
   "function": "elevon_gaps",
   "equation": "pod = y_in0 - w_pod/2 ; fin_in = (y_fin - t_fin/2) - y_in1 ; fin_out = y_out0 - (y_fin + t_fin/2) ; tip = b/2 - y_out1 ; t_fin = layers t_board",
